import {MATERIALS} from './catalog.mjs';
import {camera,ARENA_BOUNDS} from './view.mjs';
const TAU=Math.PI*2;
function ellipse(c,x,y,rx,ry,color,stroke){c.beginPath();c.ellipse(x,y,rx,ry,0,0,TAU);c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function polygon(c,pts,color,stroke){c.beginPath();pts.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.closePath();c.fillStyle=color;c.fill();if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function bottle(c,x,y,id,t){let col=MATERIALS[id].color;c.save();c.translate(x,y+Math.sin(t*3+x)*2);ellipse(c,0,14,12,4,'#091f1a55');c.fillStyle='#203c34';c.fillRect(-7,-11,14,22);c.strokeStyle=col;c.lineWidth=1.4;c.strokeRect(-7,-11,14,22);c.fillStyle=col;c.fillRect(-5,-3,10,12);c.fillStyle='#bed2bc';c.fillRect(-5,-15,10,4);c.restore()}
function enemy(c,e,t){c.save();c.translate(e.x,e.y);ellipse(c,0,e.r*.75,e.r+4,6,'#071c1755');let color=e.flash>0?'#f0e7c0':e.type===1?'#b37e82':'#91ad79';let a=t*1.5+e.id;for(let i=0;i<5;i++){let d=i*TAU/5;c.strokeStyle='#304934';c.lineWidth=4;c.beginPath();c.moveTo(Math.cos(d)*e.r*.5,Math.sin(d)*e.r*.5);c.lineTo(Math.cos(d)*e.r*1.4,Math.sin(d)*e.r*1.4+Math.sin(a+i)*2);c.stroke()}ellipse(c,0,0,e.r,e.r*.9,color,'#24382b');ellipse(c,-e.r*.3,-3,3.5,4,'#e2e5b9');ellipse(c,e.r*.3,-3,3.5,4,'#e2e5b9');ellipse(c,-e.r*.3+1,-3,1.5,2.5,'#26382b');ellipse(c,e.r*.3-1,-3,1.5,2.5,'#26382b');c.strokeStyle='#334331';c.lineWidth=2;c.beginPath();c.moveTo(-4,6);c.lineTo(4,6);c.stroke();if(e.burn>0){for(let i=0;i<3;i++){let x=(i-1)*10;polygon(c,[[x-6,8],[x-4,-10],[x+Math.sin(t*14+i)*3,-26],[x+6,5]],'#b0c4ff99');polygon(c,[[x-3,9],[x,-9],[x+4,6]],'#e0efffcc')}}c.restore()}
function player(c,x,y,angle,gun,t,inv){c.save();c.translate(x,y);if(inv>0&&Math.floor(t*16)%2===0)c.globalAlpha=.45;ellipse(c,0,22,24,8,'#081d17aa');let step=Math.sin(t*11)*2;c.fillStyle='#6c8a7f';c.fillRect(-13,12+step,10,12);c.fillRect(4,12-step,10,12);ellipse(c,0,1,18,21,'#bdccc1','#324f43');c.save();c.rotate(angle);c.fillStyle=gun.type==='water'?'#77d9f5':gun.type==='flame'?'#b8c6ff':'#bed4a8';c.fillRect(10,1,30,10);c.fillStyle='#4f6d60';c.fillRect(33,-1,10,14);c.fillStyle='#d6e0cf';c.fillRect(17,3,14,3);ellipse(c,13,13,7,6,'#a3bdb1','#365548');c.restore();ellipse(c,0,-10,19,18,'#c6d2c9','#365549');ellipse(c,0,-11,14,10,'#2d524b','#779c8d');c.strokeStyle='#b4dfc1';c.lineWidth=2;c.beginPath();c.moveTo(-8,-14);c.lineTo(0,-14);c.stroke();ellipse(c,-9,-8,3,5,'#72938a');ellipse(c,9,-8,3,5,'#72938a');ellipse(c,0,1,5,4,'#7b9d8c','#365549');c.restore()}
function chamber(c,t){c.fillStyle='#21372f';c.fillRect(0,0,1200,800);let grad=c.createRadialGradient(600,400,50,600,400,650);grad.addColorStop(0,'#34513e77');grad.addColorStop(1,'#0e211b66');c.fillStyle=grad;c.fillRect(0,0,1200,800);c.strokeStyle='#71916a13';c.lineWidth=1;for(let x=0;x<=1200;x+=50){c.beginPath();c.moveTo(x,0);c.lineTo(x,800);c.stroke()}for(let y=0;y<=800;y+=50){c.beginPath();c.moveTo(0,y);c.lineTo(1200,y);c.stroke()}c.strokeStyle='#a0c68b99';c.lineWidth=3;c.strokeRect(22,22,1156,756);c.setLineDash([5,9]);c.strokeStyle='#a9c48b1f';c.beginPath();c.arc(600,400,145,0,TAU);c.stroke();c.setLineDash([]);for(let [x,y,r]of [[72,85,.1],[1100,720,2.2],[1090,82,.4],[80,715,2]]){c.save();c.translate(x,y);c.rotate(r);c.fillStyle='#304a38';c.fillRect(-25,-15,50,30);c.strokeStyle='#678464';c.lineWidth=1;c.strokeRect(-25,-15,50,30);c.fillStyle='#96b68a';c.fillRect(-18,-10,4,20);c.fillStyle='#1b3025';c.fillRect(-8,-10,26,20);c.restore()}c.font='10px monospace';c.textAlign='center';c.fillStyle='#9bb58b33';c.fillText('REACTION FIELD — 01',600,45);c.fillText('CONTAINMENT / VALENCE',600,760)}
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.shake=0}
 draw(run,time){const c=this.ctx,r=this.canvas.getBoundingClientRect(),d=Math.min(globalThis.devicePixelRatio||1,2);if(this.canvas.width!==Math.round(r.width*d)||this.canvas.height!==Math.round(r.height*d)){this.canvas.width=Math.round(r.width*d);this.canvas.height=Math.round(r.height*d)}c.setTransform(d,0,0,d,0,0);c.fillStyle='#182c24';c.fillRect(0,0,r.width,r.height);let v=camera(r.width,r.height,run.x,run.y);c.save();c.translate(r.width/2,r.height/2);c.scale(v.scale,v.scale);c.translate(-v.x,-v.y);if(this.shake>0){c.translate((Math.random()-.5)*this.shake,(Math.random()-.5)*this.shake);this.shake*=.85;if(this.shake<.5)this.shake=0}chamber(c,time);c.save();c.beginPath();c.rect(ARENA_BOUNDS.left,ARENA_BOUNDS.top,ARENA_BOUNDS.right-ARENA_BOUNDS.left,ARENA_BOUNDS.bottom-ARENA_BOUNDS.top);c.clip();let enemies=run.state==='menu'?[{id:1,x:300,y:240,r:18,type:0},{id:2,x:890,y:550,r:18,type:0},{id:3,x:920,y:170,r:13,type:1},{id:4,x:190,y:610,r:18,type:0}]:run.enemies;for(let drop of run.drops)bottle(c,drop.x,drop.y,drop.material,time);if(run.state==='menu'){bottle(c,420,500,'water',time);bottle(c,780,300,'hydrogen',time);bottle(c,800,600,'oxygen',time)}let sprites=enemies.map(e=>({y:e.y,draw:()=>enemy(c,e,time)}));sprites.push({y:run.y,draw:()=>player(c,run.x,run.y,run.angle,run.lab.gun,time,run.inv)});sprites.sort((a,b)=>a.y-b.y).forEach(s=>s.draw());for(let b of run.bullets){c.strokeStyle=b.type==='water'?'#77d9f5':b.type==='flame'?'#bacaff':'#e9ddb4';c.lineWidth=b.type==='water'?7:4;c.lineCap='round';c.beginPath();c.moveTo(b.x-b.vx*.022,b.y-b.vy*.022);c.lineTo(b.x,b.y);c.stroke();ellipse(c,b.x,b.y,3,3,b.type==='water'?'#dcfaff':'#f2f6de')}for(let p of run.particles){c.globalAlpha=Math.min(1,p.life*3);ellipse(c,p.x,p.y,2.5,2.5,p.color)}c.globalAlpha=1;c.font='bold 14px monospace';c.textAlign='center';for(let n of run.texts){c.globalAlpha=Math.min(1,n.life*3);c.fillStyle=n.color;c.strokeStyle='#1a3027';c.lineWidth=3;c.strokeText(n.value,n.x,n.y);c.fillText(n.value,n.x,n.y)}c.globalAlpha=1;c.restore();c.restore()}
}
